// n8n Code node — place immediately after the Gemini "Analyze Image" node.
// Purpose: deterministically parse and validate the AI's extraction output.
// The AI node is non-deterministic (may add stray text, markdown fences, etc.),
// so this node never trusts raw output blindly — it parses defensively and
// flags anything that doesn't conform, rather than letting a malformed
// response silently break downstream matching logic.

const CORE_FIELDS = ["supplier_name", "delivery_note_reference", "delivery_date", "buyer_name"];

function extractRawText(item) {
  // Adjust this path if your Gemini node's output shape differs —
  // this matches the "content.parts[0].text" shape shown in your DN-019 test output.
  try {
    return item.json.content.parts[0].text;
  } catch (e) {
    // Fallback for a simpler node output shape, e.g. item.json.text directly
    return item.json.text || item.json.output || null;
  }
}

function stripMarkdownFences(raw) {
  if (!raw) return raw;
  let cleaned = raw.trim();
  if (cleaned.startsWith("```")) {
    cleaned = cleaned.replace(/^```(?:json)?/i, "").replace(/```$/, "").trim();
  }
  return cleaned;
}

function safeParseJSON(raw) {
  const cleaned = stripMarkdownFences(raw);
  try {
    return { success: true, data: JSON.parse(cleaned) };
  } catch (e) {
    return { success: false, error: e.message, raw_text: raw };
  }
}

function countUncertainOrMissing(parsed) {
  let uncertainCount = 0;
  let naCount = 0;

  for (const field of CORE_FIELDS) {
    const value = parsed[field];
    if (value === "UNCERTAIN") uncertainCount++;
    if (value === "N/A") naCount++;
  }

  // Also check line items — if the whole line_items array is empty/uncertain,
  // that's a serious data quality issue since matching depends on it.
  const lineItemsBad = parsed.line_items_confidence === "UNCERTAIN"
    || (Array.isArray(parsed.line_items) && parsed.line_items.length === 0);

  return { uncertainCount, naCount, lineItemsBad };
}

function decideReviewRoute(parsed, uncertainCount, naCount, lineItemsBad) {
  // Explicit route was requested for manual review — this is the deterministic
  // rule that decides it, not the AI. Tune thresholds as you see real data volume.
  if (parsed.extraction_attempted === false) {
    return "manual_review"; // not a valid delivery note at all
  }
  if (uncertainCount >= 2 || lineItemsBad) {
    return "manual_review"; // too much uncertainty to trust auto-matching
  }
  if (uncertainCount === 1 || naCount >= 1) {
    return "flagged_ok"; // proceed to matching, but carry a flag for visibility
  }
  return "auto_process"; // clean extraction, safe to feed into matching logic
}

// --- Main execution ---
const results = [];

for (const item of $input.all()) {
  const rawText = extractRawText(item);
  const parseResult = safeParseJSON(rawText);

  if (!parseResult.success) {
    // AI output was not valid JSON at all — this itself is a manual review case,
    // and we log the raw text so you can debug prompt issues later.
    results.push({
      json: {
        parsed_data: {
          parse_success: false,
          parse_error: parseResult.error,
          raw_ai_output: parseResult.raw_text,
          review_route: "manual_review",
          review_reason: "AI output was not valid JSON",
        }
      },
    });
    continue;
  }

  const parsed = parseResult.data;

  // Handle the explicit "not a valid delivery note" error case from the prompt
  if (parsed.error) {
    results.push({
      json: {
        parsed_data: {
          parse_success: true,
          extraction_attempted: false,
          error: parsed.error,
          review_route: "manual_review",
          review_reason: "AI reported this is not a valid delivery note",
        }
      },
    });
    continue;
  }

  // Validate all expected fields are present (defensive — AI could still omit one
  // despite instructions)
  const missingKeys = CORE_FIELDS.filter((f) => !(f in parsed));
  const { uncertainCount, naCount, lineItemsBad } = countUncertainOrMissing(parsed);
  const reviewRoute = decideReviewRoute(parsed, uncertainCount, naCount, lineItemsBad);

  results.push({
    json: {
      parsed_data: {
        parse_success: true,
        ...parsed,
        _validation: {
          missing_keys: missingKeys,
          uncertain_field_count: uncertainCount,
          na_field_count: naCount,
          line_items_flagged: lineItemsBad,
        },
        review_route: reviewRoute,
      }
    },
  });
}

return results;
